using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.RateLimiting; using TaskPilot.API.Features.Platform.RateLimiting; using TaskPilot.Application.Features.Reports;
namespace TaskPilot.API.Features.Reports;
[ApiController,Authorize,Route("api")]
public sealed class ReportsController(IWeeklyReportService reports):ControllerBase { [HttpPost("projects/{projectId:int}/ai/reports"),EnableRateLimiting(TaskPilotRateLimitingExtensions.AiPolicy)] public async Task<IActionResult> Create(int projectId,CreateWeeklyReportRequest request,CancellationToken ct)=>Result(await reports.CreateAsync(projectId,request,ct)); [HttpGet("ai/reports/{reportId:int}")] public async Task<IActionResult> Get(int reportId,CancellationToken ct)=>Result(await reports.GetAsync(reportId,ct)); [HttpPost("ai/reports/{reportId:int}/approve")] public async Task<IActionResult> Approve(int reportId,CancellationToken ct)=>Result(await reports.ReviewAsync(reportId,true,ct)); [HttpPost("ai/reports/{reportId:int}/reject")] public async Task<IActionResult> Reject(int reportId,CancellationToken ct)=>Result(await reports.ReviewAsync(reportId,false,ct)); [HttpPut("projects/{projectId:int}/ai/report-schedule")] public async Task<IActionResult> Schedule(int projectId,UpdateReportScheduleRequest request,CancellationToken ct)=>Result(await reports.UpdateScheduleAsync(projectId,request,ct)); private IActionResult Result(object r)=>StatusCode((int)((dynamic)r).Status,r); }
